CREATE TABLE style_version_meta(pack_id TEXT NOT NULL REFERENCES style_packs(id),pack_version TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('draft','published')),scope TEXT NOT NULL CHECK(scope IN('admin_only','tenants','all')),checks_json TEXT NOT NULL CHECK(json_valid(checks_json)),created_by TEXT NOT NULL,published_at INTEGER,PRIMARY KEY(pack_id,pack_version),FOREIGN KEY(pack_id,pack_version) REFERENCES style_pack_versions(pack_id,version));
